<script setup>
import {ref,computed} from 'vue'
import {regions} from '../data/regions'
import {validateProperty} from '../lib/domain'
import Icon from './Icon.vue'
const props=defineProps({initial:Object})
const emit=defineEmits(['save','close'])
const step=ref(1), errors=ref([])
const draftKey='panorama-property-draft-v1'
let saved=null; try {saved=JSON.parse(localStorage.getItem(draftKey))} catch {}
if(saved?.id) saved=null
const form=ref({...{title:'',type:'Departamento',operation:'Venta',currency:'UF',price:'',region:'',commune:'',sector:'',address:'',area:'',beds:2,baths:1,image:'',description:'',status:'Borrador'},...(props.initial || saved || {})})
const regionName=computed(()=>regions.find(r=>r.id===form.value.region)?.name)
function draft(){if(props.initial)return;try {localStorage.setItem(draftKey,JSON.stringify(form.value))} catch {} }
function save(status){errors.value=validateProperty(form.value);if(errors.value.length){step.value=1;return} emit('save',{...form.value,status,price:Number(form.value.price),area:Number(form.value.area),beds:Number(form.value.beds),baths:Number(form.value.baths)});try{localStorage.removeItem(draftKey)}catch{}}
</script>
<template><div class="modal-backdrop" @click.self="$emit('close')"><section class="modal wide" role="dialog" aria-modal="true" aria-labelledby="form-title" @keydown.esc="$emit('close')"><div class="modal-heading"><div><span class="eyebrow">TU CARTERA, AL DÍA</span><h2 id="form-title">{{initial ? 'Editar propiedad' : 'Una nueva oportunidad'}}</h2></div><button class="icon-button" aria-label="Cerrar formulario" @click="$emit('close')"><Icon name="close"/></button></div><div class="steps"><button v-for="(label,i) in ['Lo esencial','Fotos y descripción','Revisar y publicar']" :key="label" :class="{active:step===i+1}" @click="step=i+1">{{i+1}}. {{label}}</button></div><form @submit.prevent="step<3 ? step++ : save('Publicada')" @input="draft" @change="draft"><div v-if="errors.length" class="error" role="alert"><p v-for="e in errors" :key="e">{{e}}</p></div><div v-if="step===1" class="form-grid"><label class="full">Título del aviso<input v-model="form.title" required maxlength="120" placeholder="Ej. Departamento luminoso con terraza"></label><label>Operación<select v-model="form.operation"><option>Venta</option><option>Arriendo</option></select></label><label>Tipo<select v-model="form.type"><option>Departamento</option><option>Casa</option><option>Terreno</option><option>Oficina</option><option>Local comercial</option></select></label><label>Moneda<select v-model="form.currency"><option>UF</option><option>CLP</option></select></label><label>Precio<input v-model="form.price" type="number" required min="0.01" step="any"></label><label>Región<select v-model="form.region" required><option value="">Seleccionar región</option><option v-for="r in regions" :value="r.id" :key="r.id">{{r.name}}</option></select></label><label>Comuna<input v-model="form.commune" required placeholder="Ej. La Serena"><small>Ingreso manual; catálogo nacional pendiente de integración.</small></label><label>Sector o localidad<input v-model="form.sector"></label><label>Dirección privada<input v-model="form.address"><small>No se muestra en la ficha pública.</small></label><label>Superficie (m²)<input v-model="form.area" type="number" required min="0.01" step="any"></label><label>Dormitorios<input v-model="form.beds" type="number" min="0" max="99"></label><label>Baños<input v-model="form.baths" type="number" min="0" max="99"></label></div><div v-if="step===2" class="form-grid"><label class="full">URL HTTPS de la fotografía<input v-model="form.image" type="url" placeholder="https://..."><small>En esta versión se utiliza una foto por URL. Carga de archivos pendiente.</small></label><img v-if="form.image" class="form-preview full" :src="form.image" alt="Vista previa de la propiedad"><label class="full">Descripción<textarea v-model="form.description" rows="5" maxlength="4000" placeholder="Cuenta qué hace especial este lugar"></textarea></label></div><div v-if="step===3" class="review"><span class="eyebrow">VISTA PREVIA</span><h3>{{form.title || 'Tu próxima publicación'}}</h3><p>{{form.commune}} · {{regionName}}</p><p>{{form.area}} m² · {{form.beds}} dormitorios · {{form.baths}} baños</p><p>{{form.currency}} {{form.price}}</p><p>{{form.description}}</p><div class="notice">Publicar hará visible esta propiedad en el portal de este navegador. Es una demostración sin servidor.</div></div><div class="modal-actions"><button type="button" class="button secondary" @click="save('Borrador')">Guardar borrador</button><button class="button primary" type="submit">{{step<3 ? 'Continuar' : 'Publicar propiedad'}}<Icon name="arrow"/></button></div></form></section></div></template>
